const body = $json.body;
const payload = body.payload || {};
const maskedPhone = (payload.customerPhone || '').replace(/(\d{2})\d+(\d{2})$/, '$1***$2');

const itemLines = (payload.items || []).map((item) => {
  const variant = item.variantName ? ` (${item.variantName})` : '';
  const modifiers = (item.modifiers || []).map((m) => `\n   + ${m}`).join('');
  return `${item.quantity}x ${item.name}${variant}${modifiers}`;
}).join('\n');

const totalText = payload.totalMinor !== undefined ? `${(payload.totalMinor / 100).toFixed(2)}\u20ba` : '?';

const text = `\ud83d\udd34 YEN\u0130 S\u0130PAR\u0130\u015e #${payload.orderNumber ?? '?'}\n\n` +
  `M\u00fc\u015fteri: ${payload.customerName ?? '?'}\n` +
  `Telefon: ${maskedPhone}\n\n` +
  `${itemLines}\n\n` +
  `Toplam: ${totalText}\n` +
  `Teslimat: ${payload.fulfillmentType ?? '?'}` +
  (payload.note ? `\n\nNot: ${payload.note}` : '');

const orderId = payload.orderId;
const buttonRow = (labels) => labels.map(([text, status]) => ({ text, callback_data: `ord:${orderId}:${status}` }));

const replyMarkup = {
  inline_keyboard: [
    buttonRow([['Kabul Et', 'ACCEPTED'], ['Reddet', 'REJECTED']]),
    buttonRow([['Haz\u0131rlan\u0131yor', 'PREPARING'], ['Haz\u0131r', 'READY']]),
    buttonRow([['Yola \u00c7\u0131kt\u0131', 'OUT_FOR_DELIVERY'], ['Teslim Edildi', 'DELIVERED']])
  ]
};

return [{ json: { chatId: body.chatId, text, replyMarkup } }];
